type Vector2D = { x: number; y: number };
type NamedVector = { x: number; y: number; name: string };

const v: Vector2D = { x: 1, y: 2, name: 'origin' };
// Error only on fresh literal excess props:
// const bad: Vector2D = { x: 1, y: 2, z: 3 };

function magnitude({ x, y }: Vector2D) {
  return Math.hypot(x, y);
}

magnitude(v); // structural — name ignored

